lement\": \"H\",\n        \"x\": -1.8,\n        \"y\": -1,\n        \"z\": 0\n      },\n      {\n        \"id\": \"cl1\",\n        \"element\": \"Cl\",\n        \"x\": 1.8,\n        \"y\": 0.9,\n        \"z\": 0\n      },\n      {\n        \"id\": \"cl2\",\n        \"element\": \"Cl\",\n        \"x\": 1.8,\n        \"y\": -0.9,\n        \"z\": 0\n      }\n    ],\n    \"bonds\": [],\n    \"electronTransfers\": [],\n    \"atomOverrides\": {}\n  },\n  {\n    \"number\": 3,\n    \"title\": \"Electron Transfer\",\n    \"description\": \"Iron donates two electrons \\u2014 one to each hydrogen ion. Fe shrinks as it becomes Fe\\u00B2\\u207A (oxidised). The two H atoms are now neutral and drawn toward each other. The Cl\\u207B ions close in on the iron cation.\",\n    \"background\": \"default\",\n    \"atoms\": [\n      {\n        \"id\": \"fe1\",\n        \"element\": \"Fe\",\n        \"x\": 0,\n        \"y\": 0,\n        \"z\": 0\n      },\n      {\n        \"id\": \"h1\",\n        \"element\": \"H\",\n        \"x\": -1.8,\n        \"y\": 0.3,\n        \"z\": 0\n      },\n      {\n        \"id\": \"h2\",\n        \"element\": \"H\",\n        \"x\": -1.8,\n        \"y\": -0.3,\n        \"z\": 0\n      },\n      {\n        \"id\": \"cl1\",\n        \"element\": \"Cl\",\n        \"x\": 1.5,\n        \"y\": 0.5,\n        \"z\": 0\n      },\n      {\n        \"id\": \"cl2\",\n        \"element\": \"Cl\",\n        \"x\": 1.5,\n        \"y\": -0.5,\n        \"z\": 0\n      }\n    ],\n    \"bonds\": [],\n    \"electronTransfers\": [\n      {\n        \"from\": \"fe1\",\n        \"to\": \"h1\"\n      },\n      {\n        \"from\": \"fe1\",\n        \"to\": \"h2\"\n      }\n    ],\n    \"atomOverrides\": {\n      \"fe1\": {\n        \"radiusScale\": 0.8,\n        \"dimmed\": true\n      }\n    }\n  },\n  {\n    \"number\": 4,\n    \"title\": \"Products Formed\",\n    \"description\": \"The reaction is complete. Fe\\u00B2\\u207A is flanked by two Cl\\u207B ions, forming iron(II) chloride (FeCl\\u2082) dissolved in solution. The two hydrogen atoms bond together as H\\u2082 gas \\u2014 the colourless bubbles you see rising from the iron.\",\n    \"background\": \"default\",\n    \"atoms\": [\n      {\n        \"id\": \"fe1\",\n        \"element\": \"Fe\",\n        \"x\": 1.8,\n        \"y\": 0,\n        \"z\": 0\n      },\n      {\n        \"id\": \"cl1\",\n        \"element\": \"Cl\",\n        \"x\": 0.5,\n        \"y\": 0,\n        \"z\": 0\n      },\n      {\n        \"id\": \"cl2\",\n        \"element\": \"Cl\",\n        \"x\": 3.1,\n        \"y\": 0,\n        \"z\": 0\n      },\n      {\n        \"id\": \"h1\",\n        \"element\": \"H\",\n        \"x\": -2,\n        \"y\": 0,\n        \"z\": 0\n      },\n      {\n        \"id\": \"h2\",\n        \"element\": \"H\",\n        \"x\": -1.5,\n        \"y\": 0,\n        \"z\": 0\n      }\n    ],\n    \"bonds\": [\n      {\n        \"from\": \"cl1\",\n        \"to\": \"fe1\"\n      },\n      {\n        \"from\": \"cl2\",\n        \"to\": \"fe1\"\n      },\n      {\n        \"from\": \"h1\",\n        \"to\": \"h2\"\n      }\n    ],\n    \"electronTransfers\": [],\n    \"atomOverrides\": {\n      \"fe1\": {\n        \"radiusScale\": 0.8,\n        \"dimmed\": true\n      }\n    }\n  }\n]",
