verrides\": {}\n  },\n  {\n    \"number\": 2,\n    \"title\": \"O\\u2013O Bond Cleavage\",\n    \"description\": \"The catalyst weakens and snaps the O\\u2013O peroxide bond in each molecule. Four hydroxyl radicals (OH\\u2022) are released \\u2014 each is an oxygen atom with a hydrogen still attached. The O\\u2013O bonds are now broken.\",\n    \"background\": \"default\",\n    \"atoms\": [\n      {\n        \"id\": \"h1\",\n        \"element\": \"H\",\n        \"x\": -2.2,\n        \"y\": 1,\n        \"z\": 0\n      },\n      {\n        \"id\": \"o1\",\n        \"element\": \"O\",\n        \"x\": -1.5,\n        \"y\": 0.5,\n        \"z\": 0\n      },\n      {\n        \"id\": \"o2\",\n        \"element\": \"O\",\n        \"x\": 0,\n        \"y\": 0.5,\n        \"z\": 0\n      },\n      {\n        \"id\": \"h2\",\n        \"element\": \"H\",\n        \"x\": 0.7,\n        \"y\": 1,\n        \"z\": 0\n      },\n      {\n        \"id\": \"h3\",\n        \"element\": \"H\",\n        \"x\": -2.2,\n        \"y\": -1,\n        \"z\": 0\n      },\n      {\n        \"id\": \"o3\",\n        \"element\": \"O\",\n        \"x\": -1.5,\n        \"y\": -0.5,\n        \"z\": 0\n      },\n      {\n        \"id\": \"o4\",\n        \"element\": \"O\",\n        \"x\": 0,\n        \"y\": -0.5,\n        \"z\": 0\n      },\n      {\n        \"id\": \"h4\",\n        \"element\": \"H\",\n        \"x\": 0.7,\n        \"y\": -1,\n        \"z\": 0\n      }\n    ],\n    \"bonds\": [\n      {\n        \"from\": \"h1\",\n        \"to\": \"o1\"\n      },\n      {\n        \"from\": \"o2\",\n        \"to\": \"h2\"\n      },\n      {\n        \"from\": \"h3\",\n        \"to\": \"o3\"\n      },\n      {\n        \"from\": \"o4\",\n        \"to\": \"h4\"\n      }\n    ],\n    \"electronTransfers\": [],\n    \"atomOverrides\": {}\n  },\n  {\n    \"number\": 3,\n    \"title\": \"Rearrangement\",\n    \"description\": \"The OH radicals pair up and rearrange. Each oxygen atom picks up two hydrogen atoms to form a water molecule. The two remaining oxygen atoms are drawn toward each other, beginning to form the O\\u2082 molecule.\",\n    \"background\": \"default\",\n    \"atoms\": [\n      {\n        \"id\": \"h1\",\n        \"element\": \"H\",\n        \"x\": -2.1,\n        \"y\": 0.8,\n        \"z\": 0\n      },\n      {\n        \"id\": \"o1\",\n        \"element\": \"O\",\n        \"x\": -1.5,\n        \"y\": 0.3,\n        \"z\": 0\n      },\n      {\n        \"id\": \"h2\",\n        \"element\": \"H\",\n        \"x\": -0.9,\n        \"y\": 0.8,\n        \"z\": 0\n      },\n      {\n        \"id\": \"h3\",\n        \"element\": \"H\",\n        \"x\": -2.1,\n        \"y\": -0.8,\n        \"z\": 0\n      },\n      {\n        \"id\": \"o3\",\n        \"element\": \"O\",\n        \"x\": -1.5,\n        \"y\": -0.3,\n        \"z\": 0\n      },\n      {\n        \"id\": \"h4\",\n        \"element\": \"H\",\n        \"x\": -0.9,\n        \"y\": -0.8,\n        \"z\": 0\n      },\n      {\n        \"id\": \"o2\",\n        \"element\": \"O\",\n        \"x\": 1.3,\n        \"y\": 0.2,\n        \"z\": 0\n      },\n      {\n        \"id\": \"o4\",\n        \"element\": \"O\",\n        \"x\": 1.3,\n        \"y\": -0.2,\n        \"z\": 0\n      }\n    ],\n    \"bonds\": [\n      {\n        \"from\": \"h1\",\n        \"to\": \"o1\"\n      },\n      {\n        \"from\": \"h2\",\n        \"to\": \"o1\"\n      },\n      {\n        \"from\": \"h3\",\n        \"to\": \"o3\"\n      },\n      {\n        \"from\": \"h4\",\n        \"to\": \"o3\"\n      }\n    ],\n    \"electronTransfers\": [],\n    \"atomOverrides\": {}\n  },\n  {\n    \"number\": 4,\n    \"title\": \"Products Formed\",\n    \"description\": \"The reaction is complete. Two water molecules (H\\u2082O) are formed, and the two lone oxygen atoms bond together as O\\u2082 gas. This oxygen is what relights a glowing splint held at the mouth of the test tube \\u2014 the classic positive test result.\",\n    \"background\": \"default\",\n    \"atoms\": [\n      {\n        \"id\": \"h1\",\n        \"element\": \"H\",\n        \"x\": -2.4,\n        \"y\": 0.7,\n        \"z\": 0\n      },\n      {\n        \"id\": \"o1\",\n        \"element\": \"O\",\n        \"x\": -1.7,\n        \"y\": 0.2,\n        \"z\": 0\n      },\n      {\n        \"id\": \"h2\",\n        \"element\": \"H\",\n        \"x\": -1,\n        \"y\": 0.7,\n        \"z\": 0\n      },\n      {\n        \"id\": \"h3\",\n        \"element\": \"H\",\n        \"x\": -2.4,\n        \"y\": -0.7,\n        \"z\": 0\n      },\n      {\n        \"id\": \"o3\",\n        \"element\": \"O\",\n        \"x\": -1.7,\n        \"y\": -0.2,\n        \"z\": 0\n      },\n      {\n        \"id\": \"h4\",\n        \"element\": \"H\",\n        \"x\": -1,\n        \"y\": -0.7,\n        \"z\": 0\n      },\n      {\n        \"id\": \"o2\",\n        \"element\": \"O\",\n        \"x\": 1.5,\n        \"y\": 0,\n        \"z\": 0\n      },\n      {\n        \"id\": \"o4\",\n        \"element\": \"O\",\n        \"x\": 2.2,\n        \"y\": 0,\n        \"z\": 0\n      }\n    ],\n    \"bonds\": [\n      {\n        \"from\": \"h1\",\n        \"to\": \"o1\"\n      },\n      {\n        \"from\": \"h2\",\n        \"to\": \"o1\"\n      },\n      {\n        \"from\": \"h3\",\n        \"to\": \"o3\"\n      },\n      {\n        \"from\": \"h4\",\n        \"to\": \"o3\"\n      },\n      {\n        \"from\": \"o2\",\n        \"to\": \"o4\"\n      }\n    ],\n    \"electronTransfers\": [],\n    \"atomOverrides\": {}\n  }\n]",
