iption\": \"The reaction is complete. Two sodium hydroxide (NaOH) units are formed in solution \\u2014 each Na\\u207A ion is paired with an OH\\u207B group. The two freed hydrogen atoms bond together as H\\u2082 gas, producing the energetic fizzing and popping you see when sodium is dropped into water.\",\n    \"background\": \"default\",\n    \"atoms\": [\n      {\n        \"id\": \"na1\",\n        \"element\": \"Na\",\n        \"x\": -1.8,\n        \"y\": 0.5,\n        \"z\": 0\n      },\n      {\n        \"id\": \"o1\",\n        \"element\": \"O\",\n        \"x\": -0.7,\n        \"y\": 0.5,\n        \"z\": 0\n      },\n      {\n        \"id\": \"h2\",\n        \"element\": \"H\",\n        \"x\": 0.1,\n        \"y\": 0.9,\n        \"z\": 0\n      },\n      {\n        \"id\": \"na2\",\n        \"element\": \"Na\",\n        \"x\": -1.8,\n        \"y\": -0.5,\n        \"z\": 0\n      },\n      {\n        \"id\": \"o2\",\n        \"element\": \"O\",\n        \"x\": -0.7,\n        \"y\": -0.5,\n        \"z\": 0\n      },\n      {\n        \"id\": \"h4\",\n        \"element\": \"H\",\n        \"x\": 0.1,\n        \"y\": -0.9,\n        \"z\": 0\n      },\n      {\n        \"id\": \"h1\",\n        \"element\": \"H\",\n        \"x\": 2.2,\n        \"y\": 0,\n        \"z\": 0\n      },\n      {\n        \"id\": \"h3\",\n        \"element\": \"H\",\n        \"x\": 2.9,\n        \"y\": 0,\n        \"z\": 0\n      }\n    ],\n    \"bonds\": [\n      {\n        \"from\": \"na1\",\n        \"to\": \"o1\"\n      },\n      {\n        \"from\": \"h2\",\n        \"to\": \"o1\"\n      },\n      {\n        \"from\": \"na2\",\n        \"to\": \"o2\"\n      },\n      {\n        \"from\": \"h4\",\n        \"to\": \"o2\"\n      },\n      {\n        \"from\": \"h1\",\n        \"to\": \"h3\"\n      }\n    ],\n    \"electronTransfers\": [],\n    \"atomOverrides\": {\n      \"na1\": {\n        \"radiusScale\": 0.7,\n        \"dimmed\": true\n      },\n      \"na2\": {\n        \"radiusScale\":